<script setup lang="ts">
import { computed, ref, watch, onUnmounted } from "vue";
import { request, item, query, privateFile, type TopupPaymentInstruction, type Topup, type PaymentReceipt, type Page } from "@papilio/api";
import { faNumber, faDigits } from "@papilio/ui";
import PaymentAmountDetails from "./payments/PaymentAmountDetails.vue";
import { useI18n } from "vue-i18n";
import { useLocalizedFormats } from "../composables/useLocalizedFormats";
const props=defineProps<{ topupId:number; audience:"admin"|"customer"; pending:boolean; canUpload:boolean; topup?:Topup }>();
const { t, te } = useI18n();
const { date: formatDate } = useLocalizedFormats();
const instruction=ref<TopupPaymentInstruction|null>(null); const payment=ref<Topup|null>(null); const rows=ref<PaymentReceipt[]>([]); const page=ref(1); const pages=ref(1); const state=ref<"loading"|"ready"|"error">("loading"); const error=ref(""); const busy=ref(false); const selectedFile=ref<File|null>(null); const input=ref<HTMLInputElement|null>(null); const preview=ref(""); const notice=ref(""); let version=0;
const amountDetails=computed(()=>payment.value?{payableAmountRial:payment.value.amount_rial,requestedAmountRial:instruction.value?.requested_amount_rial??payment.value.requested_amount_rial,identifierMode:instruction.value?.payment_identifier_mode??payment.value.payment_identifier_mode,code4:instruction.value?.payment_identifier_code4??payment.value.payment_identifier_code4}:null);
const path=()=>`${props.audience==='admin'?'/v1/admin/payments':'/v1/customer'}/topups/${props.topupId}`;
function clearPreview():void { if(preview.value) URL.revokeObjectURL(preview.value); preview.value=""; }
function reasonLabel(reason:string):string { const key=`payments.evidence.ocrReasons.${reason}`; return te(key)?t(key):reason; }
async function load():Promise<void> { const stamp=++version; state.value="loading"; error.value=""; try { const [instructions,receipts,topup]=await Promise.all([request<{data:TopupPaymentInstruction[]}>(path()+"/instruction"),request<Page<PaymentReceipt>>(path()+`/receipts?${query({page:page.value})}`),props.topup?Promise.resolve(props.topup):item<Topup>(path())]); if(stamp!==version)return; if(topup.id!==props.topupId)throw new Error(t("payments.evidence.wrongRequest")); const captured=instructions.data[0]??null; if(captured?.topup_id!=null&&(captured.topup_id!==topup.id||captured.payable_amount_rial!==topup.amount_rial))throw new Error(t("payments.evidence.instructionMismatch")); payment.value=topup; instruction.value=captured; rows.value=receipts.data; pages.value=receipts.meta.pager?.total_pages??1; state.value="ready"; } catch(cause) { if(stamp===version) { state.value="error"; error.value=cause instanceof Error?cause.message:t("errors.request_failed"); } } }
async function view(row:PaymentReceipt):Promise<void> { const stamp=version; try { const image=await privateFile(path()+`/receipts/${row.id}`); if(stamp!==version)return; clearPreview(); preview.value=URL.createObjectURL(image); } catch(cause){ error.value=cause instanceof Error?cause.message:t("errors.request_failed"); } }
async function upload():Promise<void> { if(!selectedFile.value)return; const stamp=version; busy.value=true; error.value=""; notice.value=""; const data=new FormData(); data.set("file",selectedFile.value); try { await item<PaymentReceipt>(path()+"/receipts","POST",data); if(stamp!==version)return; selectedFile.value=null; if(input.value)input.value.value=""; notice.value=t("payments.evidence.saved"); page.value=1; await load(); } catch(cause){if(stamp===version)error.value=cause instanceof Error?cause.message:t("errors.request_failed");} finally {busy.value=false;} }
watch(()=>[props.topupId,props.audience,props.topup],()=>{clearPreview();selectedFile.value=null;if(input.value)input.value.value="";page.value=1;instruction.value=null;payment.value=props.topup??null;rows.value=[];notice.value="";void load();},{immediate:true}); onUnmounted(()=>{version++;clearPreview();});
</script>
<template><section class="form-grid"><h3>{{ t('payments.evidence.title', { id: faNumber(topupId) }) }}</h3><p v-if="error" class="message error" role="alert">{{ error }} <button class="btn small secondary" @click="load">{{ t('payments.evidence.retry') }}</button></p><p v-if="notice" role="status">{{ notice }}</p><p v-if="state==='loading'">{{ t('payments.evidence.loading') }}</p><PaymentAmountDetails v-if="amountDetails" v-bind="amountDetails" /><template v-if="instruction"><strong>{{ instruction.title }} · {{ instruction.bank_name }}</strong><p>{{ instruction.recipient }}</p><p class="tabular" dir="ltr">{{ faDigits(instruction.account) }}</p><p>{{ instruction.instructions }}</p></template><p v-else-if="state==='ready'">{{ t('payments.evidence.destinationMissing') }}</p><p>{{ t('payments.evidence.receiptNotSettlement') }}</p><article v-for="row in rows" :key="row.id" class="form-grid"><div class="detail-line"><span>{{ t('payments.evidence.receipt', { id: faNumber(row.id), date: formatDate(row.created_at), size: faNumber(row.size_bytes) }) }}</span><button class="btn small secondary" @click="view(row)">{{ t('payments.evidence.view') }}</button></div><p v-if="row.ocr_status==='not_requested'">{{ t('payments.evidence.ocrNotRequested') }}</p><p v-if="row.ocr_status==='pending'">{{ t('payments.evidence.ocrPending') }} <button class="btn small secondary" @click="load">{{ t('payments.evidence.retry') }}</button></p><p v-if="row.ocr_status==='failed'">{{ t('payments.evidence.ocrFailed') }}</p><template v-if="row.extraction"><dl class="form-grid"><div v-if="row.extraction.amount_raw"><dt>{{ t('payments.evidence.ocrAmount') }}</dt><dd>{{ faDigits(row.extraction.amount_raw) }} {{ row.extraction.currency ? t(`payments.evidence.currency.${row.extraction.currency}`) : '' }}</dd></div><div v-if="row.extraction.destination_masked"><dt>{{ t('payments.evidence.ocrDestination') }}</dt><dd dir="ltr">{{ row.extraction.destination_masked }}</dd></div><div v-if="row.extraction.field_evidence.bank_namespace"><dt>{{ t('payments.evidence.ocrBank') }}</dt><dd>{{ row.extraction.field_evidence.bank_namespace.text }}</dd></div><div v-if="row.extraction.bank_reference"><dt>{{ t('payments.evidence.ocrReference') }}</dt><dd dir="ltr">{{ row.extraction.bank_reference }}</dd></div><div v-if="row.extraction.occurred_at_raw"><dt>{{ t('payments.evidence.ocrDate') }}</dt><dd>{{ faDigits(row.extraction.occurred_at_raw) }}</dd></div><div v-if="row.extraction.transaction_status_claim"><dt>{{ t('payments.evidence.ocrStatusClaim') }}</dt><dd>{{ row.extraction.transaction_status_claim }}</dd></div></dl><p v-if="row.extraction.reason_codes.length">{{ t('payments.evidence.ocrNeedsReview') }}</p><template v-if="audience==='admin'"><section v-if="row.extraction.reason_codes.length" :aria-label="t('payments.evidence.ocrReasonCodes')"><h4>{{ t('payments.evidence.ocrReasonCodes') }}</h4><ul data-testid="ocr-reason-codes"><li v-for="reason in row.extraction.reason_codes" :key="reason"><span>{{ reasonLabel(reason) }}</span> <code>{{ reason }}</code></li></ul></section><section v-if="row.extraction.warnings.length" :aria-label="t('payments.evidence.ocrWarnings')"><h4>{{ t('payments.evidence.ocrWarnings') }}</h4><ul data-testid="ocr-warnings"><li v-for="warning in row.extraction.warnings" :key="warning"><code>{{ warning }}</code></li></ul></section><section v-if="Object.keys(row.extraction.field_evidence).length" :aria-label="t('payments.evidence.ocrFieldEvidence')"><h4>{{ t('payments.evidence.ocrFieldEvidence') }}</h4><ul class="form-grid" data-testid="ocr-field-evidence"><li v-for="(evidence, field) in row.extraction.field_evidence" :key="field"><code>{{ field }}</code>: {{ evidence.text }} · {{ faNumber(Math.round(evidence.confidence_milli/10)) }}%</li></ul></section></template></template></article><p v-if="state==='ready' && !rows.length">{{ t('payments.evidence.noReceipts') }}</p><div class="pager"><button :disabled="page<=1" @click="page--; load()">‹</button><span>{{ faNumber(page) }}</span><button :disabled="page>=pages" @click="page++; load()">›</button></div><img v-if="preview" :src="preview" :alt="t('payments.evidence.privateAlt')" style="max-width:100%;max-height:600px;object-fit:contain" /><form v-if="pending && canUpload" class="form-grid" @submit.prevent="upload"><label class="field"><span>{{ t('payments.evidence.upload') }}</span><input ref="input" type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="selectedFile=($event.target as HTMLInputElement).files?.[0]??null" /></label><button class="btn" :disabled="busy || !selectedFile">{{ t('payments.evidence.uploadButton') }}</button></form></section></template>
